<?php
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/view.php';page_start('Sources','sources.php');heading('TRANSPARENCE','La qualité commence à la source.','État des flux et fraîcheur des données. Un échec de collecte ne supprime pas les articles déjà enregistrés.');
?><div class="source-grid"><?php foreach(run('SELECT s.*,COUNT(a.id) AS count FROM sources s LEFT JOIN articles a ON a.source_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll() as $s):?><article class="panel source-card"><div class="card-meta"><span class="badge"><?=e($s['category'])?></span><span class="badge <?=$s['error']?'danger':''?>"><?=$s['enabled']?($s['error']?'Collecte en erreur':($s['success_at']?'Collectée':'En attente')):'Désactivée'?></span></div><h2><?=e($s['name'])?></h2><p><?=$s['count']?> articles conservés</p><p class="muted">Dernier succès : <?=e(when($s['success_at']?(int)$s['success_at']:null))?></p><?php if($s['error']):?><p class="error-text"><?=e($s['error'])?></p><?php endif ?><a href="<?=e($s['url'])?>" target="_blank" rel="noopener noreferrer">Voir le flux ↗</a></article><?php endforeach ?></div><?php page_end();
